<?php namespace Database\Seeders; use Illuminate\Database\Seeder;use Illuminate\Support\Facades\Hash;use App\Models\{User,Tenant,Channel,Topic,ContentAsset,Campaign,PerformanceEntry,SignalCheck,Competitor,BenchmarkCompany};
class DatabaseSeeder extends Seeder{public function run():void{$user=User::create(['name'=>'Admin','email'=>'admin@example.com','password'=>Hash::make('password')]);$channels=collect([['Website','#0f766e'],['Blog','#2563eb'],['LinkedIn','#0a66c2'],['Newsletter','#7c3aed'],['Instagram','#db2777'],['Event','#ea580c'],['Presse','#475569'],['Sonstiges','#64748b']])->map(fn($c)=>Channel::create(['name'=>$c[0],'color'=>$c[1]]));$a=Tenant::create(['name'=>'Acme GmbH','industry'=>'B2B Software','website'=>'https://example.com','description'=>'SaaS-Anbieter','tone_of_voice'=>'klar, hilfreich, kompetent']);$b=Tenant::create(['name'=>'Nordlicht Kaffee','industry'=>'Food & Beverage','website'=>'https://kaffee.example','description'=>'Regionale Kaffeemarke']);$user->tenants()->attach([$a->id,$b->id]);$user->update(['active_tenant_id'=>$a->id]);foreach([$a,$b] as $t)$t->channels()->attach($channels->pluck('id'));$topic=Topic::create(['tenant_id'=>$a->id,'title'=>'Nachhaltige Digitalisierung','description'=>'Pragmatische Digitalisierung mit Ressourcenblick.','target_audience'=>'Marketing-Leads','keywords'=>'Nachhaltigkeit, Effizienz','status'=>'active']);$topic->channels()->attach($channels->take(3)->pluck('id'));Competitor::create(['tenant_id'=>$a->id,'name'=>'Wettbewerber Eins','website'=>'https://competitor.example']);BenchmarkCompany::create(['tenant_id'=>$a->id,'name'=>'Benchmark AG','website'=>'https://benchmark.example']);$asset=ContentAsset::create(['tenant_id'=>$a->id,'topic_id'=>$topic->id,'channel_id'=>$channels[1]->id,'title'=>'Blogartikel: Effiziente Workflows','asset_type'=>'article','url'=>'https://example.com/blog','publish_date'=>now()->subDays(5),'reusable_status'=>'yes','notes'=>'Guter Evergreen-Inhalt']);$camp=Campaign::create(['tenant_id'=>$a->id,'topic_id'=>$topic->id,'channel_id'=>$channels[2]->id,'title'=>'LinkedIn Themenwoche Digitalisierung','description'=>'Kleine Kampagne ohne Overengineering.','start_date'=>now()->startOfWeek()->addDay(),'end_date'=>now()->startOfWeek()->addDays(3),'status'=>'planned','responsible_name'=>'Mara']);$camp->assets()->attach($asset);PerformanceEntry::create(['tenant_id'=>$a->id,'campaign_id'=>$camp->id,'reach'=>1200,'clicks'=>85,'engagement'=>42,'conversions'=>4,'rating'=>'normal','summary'=>'Solider Start mit hilfreichem Feedback.']);SignalCheck::create(['tenant_id'=>$a->id,'topic_id'=>$topic->id,'title'=>'Lagecheck Digitalisierung Q1','market_signal_notes'=>'Kunden fragen nach Effizienz und Nachhaltigkeit.','competitor_notes'=>'Wettbewerber betonen Automatisierung.','benchmark_notes'=>'Benchmark-Unternehmen nutzen klare Praxisbeispiele.','internal_content_summary'=>'Blogartikel und LinkedIn-Posts vorhanden.','ai_summary'=>'Platzhalter für spätere KI-Zusammenfassung.','cautious_next_steps'=>'Bestehenden Blogartikel in drei LinkedIn-Posts zerlegen.','status'=>'draft']);}}
